--Q1. What is the total revenue generated by male vs. female customers?
SELECT 
    gender, 
    COUNT(*) AS total_customer,
    SUM(purchase_amount) AS revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY gender;


--Q2. Which customers used a discount but still spent more than the average purchase amount? 
SELECT 
    customer_id, 
    purchase_amount 
FROM customer_data 
WHERE discount_applied = 'Yes' AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer_data);

-- Q3. Which are the top 5 products with the highest average review rating?
SELECT
    item_purchased, 
    ROUND(AVG(review_rating), 2) AS average_rating,
    COUNT(*) AS total_reviews
FROM customer_data
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
SELECT 
    shipping_type, 
    COUNT(*) AS number_of_customers,
    ROUND(AVG(purchase_amount),2) AS avg_purchase_amount
FROM customer_data
WHERE shipping_type IN ('Standard','Express')
GROUP BY shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue 
--between subscribers and non-subscribers.
SELECT 
    subscription_status, 
    COUNT(*) AS total_customer, 
    ROUND(AVG(purchase_amount),2) AS average_spend,
    SUM(purchase_amount) as total_revenue
FROM customer_data 
GROUP BY subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT item_purchased,
       ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment. 
with customer_type as (
    SELECT 
        customer_id, 
        previous_purchases,
        CASE 
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer_data
)
SELECT
    customer_segment,
    COUNT(*) AS total_customers
FROM customer_type
GROUP BY customer_segment
ORDER BY total_customers DESC;

--Q8. What are the top 3 most purchased products within each category? 
 WITH product_count AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_purchases,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(*) DESC, item_purchased
        ) AS item_rank
    FROM customer_data
    GROUP BY category, item_purchased
)

SELECT
    category,
    item_purchased,
    total_purchases,
    item_rank
FROM product_count
WHERE item_rank <= 3
ORDER BY category, item_rank;

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT
    CASE
        WHEN previous_purchases > 5 THEN 'Repeat Buyers'
        ELSE 'Non-Repeat Buyers'
    END AS customer_type,
    COUNT(*) AS total_customers,
    SUM(
        CASE WHEN subscription_status = 'Yes'
        THEN 1 ELSE 0 END
    ) AS subscribed_customers,
    ROUND(
        100.0 * SUM(
            CASE WHEN subscription_status = 'Yes'
            THEN 1 ELSE 0 END
        ) / COUNT(*),
        2
    ) AS subscription_rate

FROM customer_data
GROUP BY customer_type;

--Q10. What is the revenue contribution of each age group? 
SELECT 
    age_group, 
    COUNT(*) AS total_customers,
    SUM(purchase_amount) as total_revenue 
    ROUND(
        SUM(purchase_amount) * 100.0 /
        (SELECT SUM(purchase_amount) FROM customer_data),
        2
    ) AS revenue_percentage
FROM customer_data
GROUP BY age_group
ORDER BY total_revenue DESC;

-- Q11. Which product categories generate the highest revenue?
SELECT
    category,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount,
    ROUND(
        SUM(purchase_amount) * 100.0 /
        (SELECT SUM(purchase_amount) FROM customer_data),
        2
    ) AS revenue_percentage
FROM customer_data
GROUP BY category
ORDER BY total_revenue DESC;

-- Q12. Which season generates the highest revenue?
SELECT
    season,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY season
ORDER BY total_revenue DESC;

-- Q13. Which payment methods are most popular?
SELECT
    payment_method,
    COUNT(*) AS total_transactions,
    ROUND(
        COUNT(*) * 100.0 /
        (SELECT COUNT(*) FROM customer_data),
        2
    ) AS usage_percentage,
    SUM(purchase_amount) AS total_revenue
FROM customer_data
GROUP BY payment_method
ORDER BY total_transactions DESC;

-- Q14. Which locations generate the highest revenue?
SELECT
    location,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY location
ORDER BY total_revenue DESC
LIMIT 10;

-- Q15. How do average purchase amounts differ between discounted and non-discounted purchases?
SELECT 
    discount_applied,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY discount_applied;

-- Q16. Which age group has the highest average purchase amount?
SELECT 
    age_group,
    COUNT(*) AS total_customers,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY age_group
ORDER BY avg_purchase_amount DESC;

-- Q17. Does purchase frequency relate to customer spending?
SELECT 
    frequency_of_purchases,
    purchase_frequency_days,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount), 2) AS avg_purchase_amount
FROM customer_data
GROUP BY frequency_of_purchases,
    purchase_frequency_days
ORDER BY purchase_frequency_days DESC;

-- Q18. What are the top 3 most purchased products in each location?
WITH location_products AS (
    SELECT
        location,
        item_purchased,
        COUNT(*) AS total_purchases,

        DENSE_RANK() OVER (
            PARTITION BY location
            ORDER BY COUNT(*) DESC
        ) AS product_rank

    FROM customer_data
    GROUP BY location, item_purchased
)

SELECT
    location,
    item_purchased,
    total_purchases,
    product_rank
FROM location_products
WHERE product_rank <= 3
ORDER BY location, product_rank;

-- Q19. How are customer purchase amounts distributed across four quartiles?
WITH customer_spending AS (
    SELECT
        customer_id,
        purchase_amount,
        NTILE(4) OVER (
            ORDER BY purchase_amount
        ) AS spending_quartile
    FROM customer_data
)

SELECT
    spending_quartile,
    COUNT(*) AS total_customers,
    MIN(purchase_amount) AS min_spending,
    MAX(purchase_amount) AS max_spending,
    ROUND(AVG(purchase_amount), 2) AS avg_spending
FROM customer_spending
GROUP BY spending_quartile
ORDER BY spending_quartile;

-- Q20. How does subscription status vary across age groups?
SELECT
    age_group,
    COUNT(*) AS total_customers,

    SUM(CASE
        WHEN subscription_status = 'Yes' THEN 1
        ELSE 0
    END) AS subscribed_customers,

    SUM(CASE
        WHEN subscription_status = 'No' THEN 1
        ELSE 0
    END) AS non_subscribed_customers,

    ROUND(
        100.0 * SUM(
            CASE WHEN subscription_status = 'Yes' THEN 1 ELSE 0 END
        ) / COUNT(*),
        2
    ) AS subscription_percentage

FROM customer_data
GROUP BY age_group
ORDER BY subscription_percentage DESC;